"""
Fibre products of coverings and Mackey's double coset formula.
==============================================================

Two connected coverings of a K(G,1), classified by subgroups H and K of
G = pi_1, can be laid over one another.  The resulting fibre product is the
G-set (G/H) x (G/K) with the diagonal monodromy.  It is usually disconnected,
and its structure is exactly Mackey's double coset formula:

  * the connected components are indexed by the double cosets  H \\ G / K;
  * the component through (H, gK) is the connected covering classified by
        H  intersect  g K g^{-1},
    of degree [G : H ∩ gKg^{-1}];
  * the fibre product is connected if and only if G = H*K.

Taking K = H recovers regularity from the fibre-product side: the self-fibre
product of G/H splits into [G:H] copies of G/H exactly when H is normal.

This script verifies all of the above by direct computation over S3, S4, the
Klein four group and the dihedral group of order 8.
"""

from __future__ import annotations

from typing import Callable, Dict, FrozenSet, List, Sequence, Tuple

Elem = Tuple[int, ...]


# ---------------------------------------------------------------------------
# small permutation groups
# ---------------------------------------------------------------------------

def permutations(xs: List[int]) -> List[List[int]]:
    if not xs:
        return [[]]
    out: List[List[int]] = []
    for i, x in enumerate(xs):
        for rest in permutations(xs[:i] + xs[i + 1:]):
            out.append([x] + rest)
    return out


class PermGroup:
    """A group of permutations of {0, ..., n-1}, given by a list of elements."""

    def __init__(self, name: str, n: int, elements: Sequence[Elem]) -> None:
        self.name = name
        self.n = n
        self.elements = list(elements)
        self.identity: Elem = tuple(range(n))

    def mul(self, a: Elem, b: Elem) -> Elem:
        return tuple(a[b[i]] for i in range(self.n))

    def inv(self, a: Elem) -> Elem:
        out = [0] * self.n
        for i, v in enumerate(a):
            out[v] = i
        return tuple(out)

    def closure(self, gens: Sequence[Elem]) -> FrozenSet[Elem]:
        pts = {self.identity}
        frontier = [self.identity]
        ext = list(gens) + [self.inv(g) for g in gens]
        while frontier:
            x = frontier.pop()
            for g in ext:
                y = self.mul(x, g)
                if y not in pts:
                    pts.add(y)
                    frontier.append(y)
        return frozenset(pts)

    def subgroups(self) -> List[FrozenSet[Elem]]:
        found = {frozenset({self.identity})}
        changed = True
        while changed:
            changed = False
            for s in list(found):
                for g in self.elements:
                    if g in s:
                        continue
                    bigger = self.closure(list(s) + [g])
                    if bigger not in found:
                        found.add(bigger)
                        changed = True
        return sorted(found, key=len)

    def cosets(self, sub: FrozenSet[Elem]) -> List[FrozenSet[Elem]]:
        """The left cosets gH, as frozensets."""
        seen: List[FrozenSet[Elem]] = []
        for g in self.elements:
            coset = frozenset(self.mul(g, h) for h in sub)
            if coset not in seen:
                seen.append(coset)
        return seen


def symmetric(n: int) -> PermGroup:
    return PermGroup(f"S{n}", n, [tuple(p) for p in permutations(list(range(n)))])


def klein_four() -> PermGroup:
    els = [(0, 1, 2, 3), (1, 0, 2, 3), (0, 1, 3, 2), (1, 0, 3, 2)]
    return PermGroup("V = Z/2 x Z/2", 4, els)


def dihedral8() -> PermGroup:
    """The symmetries of a square, as permutations of its four vertices."""
    g = PermGroup("D4", 4, [])
    r = (1, 2, 3, 0)     # rotation
    s = (1, 0, 3, 2)     # reflection
    g.elements = sorted(g.closure([r, s]))
    return g


# ---------------------------------------------------------------------------
# fibre products
# ---------------------------------------------------------------------------

def fibre_product_components(
    g: PermGroup, H: FrozenSet[Elem], K: FrozenSet[Elem]
) -> List[Dict[str, object]]:
    """
    The orbits of G on (G/H) x (G/K), with the classifying subgroup of each
    component (the stabiliser of a chosen point) and its degree.
    """
    def act(x: Elem, p: Tuple[FrozenSet[Elem], FrozenSet[Elem]]):
        return (frozenset(g.mul(x, u) for u in p[0]),
                frozenset(g.mul(x, u) for u in p[1]))

    # every orbit contains a point of the form (H, bK): translate the first
    # coordinate back to the trivial coset.  Then the stabiliser is exactly
    # H ∩ bKb^{-1}, which is the classifying subgroup of that component.
    seen: List[FrozenSet[Tuple[FrozenSet[Elem], FrozenSet[Elem]]]] = []
    out: List[Dict[str, object]] = []
    for b in g.elements:
        p0 = (H, frozenset(g.mul(b, u) for u in K))
        orbit = frozenset(act(x, p0) for x in g.elements)
        if orbit in seen:
            continue
        seen.append(orbit)
        stab = frozenset(x for x in g.elements if act(x, p0) == p0)
        out.append({"size": len(orbit), "stab_order": len(stab),
                    "degree": len(g.elements) // len(stab), "stab": stab,
                    "witness": b})
    out.sort(key=lambda r: -r["size"])
    return out


def double_cosets(g: PermGroup, H: FrozenSet[Elem], K: FrozenSet[Elem]
                  ) -> List[FrozenSet[Elem]]:
    """The double cosets HgK."""
    seen: List[FrozenSet[Elem]] = []
    for x in g.elements:
        dc = frozenset(g.mul(g.mul(h, x), k) for h in H for k in K)
        if dc not in seen:
            seen.append(dc)
    return seen


def check(g: PermGroup) -> None:
    print("=" * 74)
    print(f"base K({g.name},1):  fibre products of connected coverings")
    print("=" * 74)
    subs = g.subgroups()
    print(f"  {'[G:H]':>6} {'[G:K]':>6} | {'#components':>12} {'#double cosets':>15} |"
          f" {'connected iff G=HK':>19}")
    print("  " + "-" * 68)
    for H in subs:
        for K in subs:
            comps = fibre_product_components(g, H, K)
            dcs = double_cosets(g, H, K)
            # Mackey: components <-> double cosets
            assert len(comps) == len(dcs)
            # each component is classified by an intersection H ∩ gKg^{-1}
            for comp in comps:
                x = comp["witness"]
                expected = frozenset(
                    h for h in H
                    if h in {g.mul(g.mul(x, k), g.inv(x)) for k in K}
                )
                assert comp["stab"] == expected, "component is not H ∩ gKg^{-1}"
            product_set = {g.mul(h, k) for h in H for k in K}
            connected = len(comps) == 1
            assert connected == (len(product_set) == len(g.elements))
            if len(H) > 1 and len(K) > 1 and len(H) < len(g.elements):
                print(f"  {len(g.elements)//len(H):>6} {len(g.elements)//len(K):>6} |"
                      f" {len(comps):>12} {len(dcs):>15} |"
                      f" {str(connected):>19}")
    print("  all Mackey assertions verified.")
    print()


def regularity_from_fibre_products(g: PermGroup) -> None:
    print("=" * 74)
    print(f"base K({g.name},1):  self-fibre products detect regular coverings")
    print("=" * 74)
    print(f"  {'[G:H]':>6} | {'#components of (G/H)x(G/H)':>28} | {'H normal':>9}")
    print("  " + "-" * 52)
    for H in g.subgroups():
        comps = fibre_product_components(g, H, H)
        normal = all(
            frozenset(g.mul(g.mul(x, h), g.inv(x)) for h in H) == H
            for x in g.elements
        )
        index = len(g.elements) // len(H)
        # regular <=> the self-fibre product splits into `index` copies of G/H
        split = all(c["size"] == index for c in comps) and len(comps) == index
        assert split == normal
        print(f"  {index:>6} | {len(comps):>28} | {str(normal):>9}")
    print("  a covering is regular exactly when its self-fibre product splits")
    print("  into [G:H] copies of itself.")
    print()


def main() -> None:
    print()
    print("Fibre products of coverings, double cosets, and regularity")
    print()
    for g in (klein_four(), symmetric(3), dihedral8(), symmetric(4)):
        check(g)
    regularity_from_fibre_products(symmetric(3))
    regularity_from_fibre_products(dihedral8())
    print("All assertions passed.")


if __name__ == "__main__":
    main()

