"""
Algorithm A: enumeration of the connected coverings of K(G,1) for finite G,
by conjugacy classes of subgroups.

For each conjugacy class of subgroups H <= G it reports the covering data:
number of sheets [G:H], fundamental group H of the total space, the deck
transformation group N_G(H)/H, and whether the covering is regular (H normal).
"""

from __future__ import annotations

from typing import Callable, Dict, FrozenSet, List, Sequence, Tuple

Elem = Tuple[int, ...]


def closure(
    gens: Sequence[Elem],
    identity: Elem,
    mul: Callable[[Elem, Elem], Elem],
    inv: Callable[[Elem], Elem],
) -> FrozenSet[Elem]:
    """Subgroup generated by `gens`: closure under multiplication and inverses."""
    pts = {identity}
    frontier = [identity]
    extended = list(gens) + [inv(g) for g in gens]
    while frontier:
        x = frontier.pop()
        for g in extended:
            y = mul(x, g)
            if y not in pts:
                pts.add(y)
                frontier.append(y)
    return frozenset(pts)


def all_subgroups(
    elements: Sequence[Elem],
    identity: Elem,
    mul: Callable[[Elem, Elem], Elem],
    inv: Callable[[Elem], Elem],
) -> List[FrozenSet[Elem]]:
    """All subgroups, obtained by repeatedly adjoining one element at a time."""
    found = {closure([], identity, mul, inv)}
    changed = True
    while changed:
        changed = False
        for sub in list(found):
            for g in elements:
                if g in sub:
                    continue
                bigger = closure(list(sub) + [g], identity, mul, inv)
                if bigger not in found:
                    found.add(bigger)
                    changed = True
    return sorted(found, key=len)


def classify_coverings(
    elements: Sequence[Elem],
    identity: Elem,
    mul: Callable[[Elem, Elem], Elem],
    inv: Callable[[Elem], Elem],
) -> List[Dict[str, object]]:
    """One record per isomorphism class of connected covering of K(G,1)."""
    order = len(elements)

    def conj(sub: FrozenSet[Elem], g: Elem) -> FrozenSet[Elem]:
        gi = inv(g)
        return frozenset(mul(mul(g, h), gi) for h in sub)

    records: List[Dict[str, object]] = []
    seen: set = set()
    for sub in all_subgroups(elements, identity, mul, inv):
        if sub in seen:
            continue
        orbit = {conj(sub, g) for g in elements}
        seen |= orbit
        normalizer = [g for g in elements if conj(sub, g) == sub]
        records.append(
            {
                "sheets": order // len(sub),
                "pi1_order": len(sub),
                "regular": len(orbit) == 1,
                "deck_order": len(normalizer) // len(sub),
                "class_size": len(orbit),
                "representative": sorted(sub),
            }
        )
    records.sort(key=lambda r: (r["sheets"], r["pi1_order"]))
    return records


def symmetric_group(n: int) -> Tuple[List[Elem], Elem, Callable, Callable]:
    """S_n with permutations as tuples; p sends i to p[i]."""

    def perms(xs: List[int]) -> List[List[int]]:
        if not xs:
            return [[]]
        out: List[List[int]] = []
        for i, x in enumerate(xs):
            for rest in perms(xs[:i] + xs[i + 1:]):
                out.append([x] + rest)
        return out

    elements = [tuple(p) for p in perms(list(range(n)))]

    def mul(a: Elem, b: Elem) -> Elem:
        return tuple(a[b[i]] for i in range(n))

    def inv(a: Elem) -> Elem:
        out = [0] * n
        for i, v in enumerate(a):
            out[v] = i
        return tuple(out)

    return elements, tuple(range(n)), mul, inv


if __name__ == "__main__":
    for n in (3, 4):
        els, idt, mult, invert = symmetric_group(n)
        print(f"connected coverings of K(S{n},1):")
        for rec in classify_coverings(els, idt, mult, invert):
            print(
                f"  sheets={rec['sheets']:<3} |pi1(cover)|={rec['pi1_order']:<3}"
                f" regular={str(rec['regular']):<5} |deck|={rec['deck_order']:<3}"
                f" subgroups in class={rec['class_size']}"
            )
        print()
